/* @lc app=leetcode id=3463 lang=kotlin */ class Solution { fun cm(a: Int, b: Int): Int = if (b > a) 0 else (0 until b).fold(1) { r, t -> r * (a - t) / (t + 1) } fun lu(n: Int, k: Int, p: Int): Int = generateSequence(n to k) { (a, b) -> if (a == 0 && b == 0) null else a / p to b / p }.fold(1) { acc, (a, b) -> acc * cm(a % p, b % p) % p } fun hasSameDigits(s: String): Boolean = (s.length - 2).let { N -> (0..N).map { i -> (0..9).first { x -> x % 2 == lu(N, i, 2) && x % 5 == lu(N, i, 5) } }.let { c -> (0..N).sumOf { c[it] * (s[it] - '0') } % 10 == (0..N).sumOf { c[it] * (s[it + 1] - '0') } % 10 } } }